mapper.select:
select id, plan_id as planId, provider_product_id as providerProductId,
       provider_price_id as providerPriceId, currency, billing_period as billingPeriod
from cm_membership_plan_payment_prices
where plan_id = #{planId}
  and provider = 'stripe'
  and environment = #{environment}
  and mode = 'subscription'
  and currency = #{currency}
  and billing_period = #{billingPeriod}
  and status = 'active'
limit 1

select id, user_id as userId, provider, environment,
       provider_customer_id as providerCustomerId
from cm_payment_customers
where user_id = #{userId}
  and provider = #{provider}
  and environment = #{environment}
limit 1

mapper.update:
update cm_payment_webhook_events
set process_status = #{processStatus},
    process_message = #{processMessage},
    processed_at = now(),
    updated_at = now()
where provider = #{provider}
  and environment = #{environment}
  and event_id = #{eventId}

mapper.insert:
insert ignore into cm_payments
    (id, order_id, provider, environment, provider_payment_id, provider_invoice_id,
     provider_subscription_id, provider_charge_id, provider_checkout_session_id,
     status, raw_status, amount_cents, currency, failure_reason, paid_at)
select #{id}, #{orderId}, #{provider}, #{environment}, #{paymentId}, #{invoiceId},
       #{subscriptionId}, #{chargeId}, #{checkoutSessionId},
       #{status}, #{rawStatus}, #{amountCents}, #{currency}, #{failureReason}, #{paidAt}
from dual
where not exists (
    select 1 from cm_payments
    where provider = #{provider}
      and environment = #{environment}
      and provider_invoice_id = #{invoiceId}
)

mapper.update:
update cm_payments
set status = 'refunded',
    raw_status = #{rawStatus},
    updated_at = now()
where provider = #{provider}
  and environment = #{environment}
  and (
      (#{paymentId} is not null and provider_payment_id = #{paymentId})
      or (#{chargeId} is not null and provider_charge_id = #{chargeId})
  )
